            title = "The Station of Shared Sketches",
            tagline = "A drawing club helps a town notice the stories hidden in familiar places.",
            parts = listOf(
                StoryPart(1, "The Sketch on the Bench", listOf("During a school art walk, Zainab found a pencil sketch tucked beneath a public bench at the old station. It showed the platform clock and a row of market stalls.", "The station noticeboard invited people to leave lost property at the office, so she handed the sketch to the attendant rather than keeping it.", "The attendant recognised the station in the drawing and suggested asking the local library about its history.")),
                StoryPart(2, "A Drawing Club Begins", listOf("The librarian found several similar sketches in a folder donated by a former art teacher.", "The drawings showed ordinary places: a bus shelter, a bakery doorway, a shaded corner, and the station steps.", "Zainab invited classmates to form a drawing club and learn who had made them.")),
                StoryPart(3, "The Artist's Initials", listOf("A small set of initials appeared in the corner of each page. The school archive matched them to a former student named Kunle.", "The school office contacted him through the alumni association. He remembered drawing places where people waited, met, and helped one another.", "He agreed to visit and explain the project.")),
                StoryPart(4, "Looking More Closely", listOf("Kunle said the sketches were part of an exercise called 'Places That Hold Stories'. He had wanted to show that familiar locations mattered because of the people who used them.", "The club compared each drawing with current public photographs and noted which buildings had changed.", "They decided to label old scenes with their dates instead of presenting them as current views.")),
                StoryPart(5, "A Story Beside a Picture", listOf("The librarian suggested pairing each sketch with a short memory from someone who knew the place.", "The students invited residents to contribute voluntarily and explained that names would only be included with permission.", "One shopkeeper described how the bakery doorway became a meeting point before the morning market opened.")),
                StoryPart(6, "A Difference of Memory", listOf("Two residents remembered the station clock being repaired in different years. The club checked newspaper archives and maintenance notices.", "The records supported one date, while the residents' memories remained valuable as personal recollections.", "The students labelled the verified date separately from the memories.")),
                StoryPart(7, "The New Sketch Walk", listOf("With the teacher's approval, the club planned a supervised walk along public routes and selected safe places to draw.", "They avoided private property and did not photograph people without permission.", "Each student chose a place and wrote down why it mattered to the community.")),
                StoryPart(8, "The Exhibition Draft", listOf("The club arranged sketches, dates, and approved memories in a draft exhibition at the library.", "The librarian checked captions for accuracy, readability, and privacy. One contributor asked for a name to be removed, and the students made the change.", "They learned that a good exhibition must respect the people whose stories it shares.")),
                StoryPart(9, "The Opening Afternoon", listOf("Kunle returned for the opening and saw the new drawings beside his old work.", "Visitors recognised familiar places and offered corrections or additional memories through the librarian.", "The club kept a record of suggested changes instead of editing historical captions without checking.")),
                StoryPart(10, "Places Worth Noticing", listOf("The library kept the exhibition for the school term and archived the original sketches safely.", "The drawing club planned another walk, this time focusing on public spaces that helped people learn, rest, and meet.", "Zainab looked again at the station bench. It seemed ordinary until someone had taken time to notice it. Now she understood that careful attention could turn a familiar place into a shared story."))
